rc = rd(f'{SP}/ch26_compile_recon.out'); assert 'RECON DONE' in rc; cl = rd(f'{SP}/ch26_callees.out'); NF = len(re.findall(r'^FACT ', cl, re.M)); NFL = len(re.findall(r'^FAIL ', cl, re.M))
er = rd(f'{SP}/ch26_exam_rows.out'); ERC = int(R(r'^TOTAL CHARS (\d+)$', er, 'exam chars')); NDC = int(R(r'^DISTINCT CITATIONS: (\d+) \|', er, 'distinct'))
